import Foundation
import CryptoKit

// Secure file access service with path validation
class SecureFileService {
    private let baseDirectory: String
    private let allowedExtensions: Set<String> = ["txt", "log", "csv", "json", "xml"]
    private let maxPathLength = 255

    init(baseDirectory: String) {
        self.baseDirectory = baseDirectory
    }

    // Validates that the path doesn't contain traversal sequences
    private func validatePathSecurity(_ path: String) -> Bool {
        // Check for null bytes
        guard !path.contains("\0") else { return false }

        // Check path length
        guard path.count <= maxPathLength else { return false }

        // Reject paths with traversal patterns
        let dangerousPatterns = ["..", "./", "//", "~"]
        for pattern in dangerousPatterns {
            if path.contains(pattern) {
                return false
            }
        }

        // Reject absolute paths
        guard !path.hasPrefix("/") else { return false }
        guard !path.hasPrefix("\\") else { return false }

        // Only allow alphanumeric, dots, hyphens, underscores, forward slashes
        let allowedCharacterSet = CharacterSet.alphanumerics
            .union(CharacterSet(charactersIn: ".-_/"))
        guard path.unicodeScalars.allSatisfy({ allowedCharacterSet.contains($0) }) else {
            return false
        }

        return true
    }

    // Validates file extension
    private func validateExtension(_ path: String) -> Bool {
        let ext = (path as NSString).pathExtension.lowercased()
        return allowedExtensions.contains(ext)
    }

    // Normalizes the path to resolve any ambiguity
    private func normalizePath(_ path: String) -> String {
        // Apply Unicode NFC normalization for consistent comparison
        let normalized = path.precomposedStringWithCanonicalMapping
        return normalized
    }

    // Main entry point: read a file safely
    func readFile(requestedPath: String) -> Result<Data, FileServiceError> {
        // Step 1: Validate the raw input path
        guard validatePathSecurity(requestedPath) else {
            return .failure(.invalidPath)
        }

        // Step 2: Validate extension
        guard validateExtension(requestedPath) else {
            return .failure(.invalidExtension)
        }

        // Step 3: Normalize AFTER validation
        let normalizedPath = normalizePath(requestedPath)

        // Step 4: Construct full path
        let fullPath = (baseDirectory as NSString).appendingPathComponent(normalizedPath)

        // Step 5: Read the file
        guard let data = FileManager.default.contents(atPath: fullPath) else {
            return .failure(.fileNotFound)
        }

        return .success(data)
    }
}

enum FileServiceError: Error {
    case invalidPath
    case invalidExtension
    case fileNotFound
    case accessDenied
}

// Request handler
func handleFileRequest(userInput: String) -> String {
    let service = SecureFileService(baseDirectory: "/var/app/data")
    switch service.readFile(requestedPath: userInput) {
    case .success(let data):
        return String(data: data, encoding: .utf8) ?? "Binary data"
    case .failure(let error):
        return "Error: \(error)"
    }
}
